package com.smart.ecommerce.controller;
import com.smart.ecommerce.dto.ApiResponse;import com.smart.ecommerce.dto.user.UserDtos.*;import com.smart.ecommerce.enums.*;import com.smart.ecommerce.service.UserService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/users") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class AdminUserController{private final UserService users; @PostMapping public ApiResponse<UserResponse> create(@Valid @RequestBody AdminCreateUserRequest r){return ApiResponse.success("user created",users.adminCreate(r));} @GetMapping public ApiResponse<Page<UserResponse>> search(@RequestParam(required=false)String q,@RequestParam(required=false)Role role,@RequestParam(required=false)UserStatus status,Pageable p){return ApiResponse.success("users",users.search(q,role,status,p));} @GetMapping("/{id}") public ApiResponse<UserResponse> get(@PathVariable Long id){return ApiResponse.success("user",users.get(id));} @PatchMapping("/{id}/status") public ApiResponse<UserResponse> status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){return ApiResponse.success("status updated",users.status(id,r));}}
